    ": 각 점선 구역 내부 숫자의 총합은 좌상단에 적힌 목표 합계와 같아야 하며, 같은 케이지 내부에서는 숫자가 중복될 수 없습니다.": ": 各点線区域内の数字の総和は、左上端に書かれた目標合計と同じでなければならず、同じケージ内では数字は重複することはできません。",
    ": 모든 행, 열, 3×3 박스에 1부터 9까지의 숫자가 중복 없이 1개씩 들어갑니다.": "：すべての行、列、3×3ボックスに1から9までの数字が重複せずに1つずつ入ります。",
    ": 전문가 난이도는 단 0~2개의 1칸 확정 단서만 주어지지만, 결코 임의로 찍을 필요 없이 100% 논리만으로 완벽히 풀리도록 설계되었습니다.": ": 専門家難易度はたった0～2個の1マス確定手がかりだけ与えられますが、決して任意に撮る必要なく100%ロジックだけで完全に解けるように設計されています。",
    ": 판은 처음에 완전히 비어있습니다. 단, 1칸짜리 케이지(예: 좌상단 7)는 그 칸의 숫자가 확정 7이므로, 이 칸들을 출발점으로 삼아 연역적 추론을 전개합니다.": ": 版は最初は完全に空です。ただし、1マスのケージ（例、左上段7）は、そのマスの数字が確定7なので、これらのマスを出発点にして演繹的推論を展開します。",
