    ": 각 점선 구역 내부 숫자의 총합은 좌상단에 적힌 목표 합계와 같아야 하며, 같은 케이지 내부에서는 숫자가 중복될 수 없습니다.": "：每個虛線區域內的數字總數必須等於左上角所寫的目標總數，且同一籠內的數字不能重疊。",
    ": 모든 행, 열, 3×3 박스에 1부터 9까지의 숫자가 중복 없이 1개씩 들어갑니다.": "：每行、每列、3×3的方格中包含1到9中的一個數字，且不重複。",
