    ": 판은 처음에 완전히 비어있습니다. 단, 1칸짜리 케이지(예: 좌상단 7)는 그 칸의 숫자가 확정 7이므로, 이 칸들을 출발점으로 삼아 연역적 추론을 전개합니다.": "：棋盤最初是完全空的。然而，在單細胞籠中（例如左上角的 7），該細胞中的數字是確定的 7，因此以這些細胞為起點來發展演繹推理。",
