    "3×3 블록 또는 1개 행의 모든 수의 합은 항상 45입니다. 박스를 삐져나온 케이지의 차이로 특정 칸을 100% 확정할 수 있습니다.": "La suma de todos los números en un bloque o fila de 3 × 3 es siempre 45. Una caja específica puede confirmarse al 100% por la diferencia en la jaula que sobresale de la caja.",
    "3단계: 인간 연역 추론 검증 완료! ({0}/81칸 확정)": "Paso 3: ¡Verificación del razonamiento deductivo humano completada! ({0}/81 espacios confirmados)",
    "3단계: 인간 연역 판별 중... ({0}/81칸 확정 · 시도 #{1})": "Paso 3: Determinando la deducción humana... ({0}/81 espacios confirmados · Intento #{1})",
    "3분 이내에 퍼즐 완료": "Completa el rompecabezas en menos de 3 minutos.",
    "3연승 달성": "Logró 3 victorias consecutivas",
    "3일 연속": "3 días seguidos",
    "3행 5열": "3 filas 5 columnas",
    "4. 전문가 모드의 0~2개 앵커": "4. 0-2 anclajes en modo experto",
    "45를 넘는 {0}{1} {2} 밖으로 튀어나온 칸의 합이고, 그중 빈칸은 {3} 하나입니다.": "La suma de {0}{1} {2} celdas que sobresalen supera las 45, y entre ellas, {3} es un espacio en blanco.",
    "45의 법칙": "Regla del 45",
    "45의 법칙 (Rule of 45):": "Regla del 45:",
    "9개의 셀에 모두 채워 넣은 숫자를 키패드에서 비활성화합니다": "Desactiva los números completados en las 9 celdas del teclado.",
    ": 각 점선 구역 내부 숫자의 총합은 좌상단에 적힌 목표 합계와 같아야 하며, 같은 케이지 내부에서는 숫자가 중복될 수 없습니다.": ": El número total de números dentro de cada área de puntos debe ser igual al total objetivo escrito en la esquina superior izquierda, y los números no pueden superponerse dentro de la misma jaula.",
    ": 모든 행, 열, 3×3 박스에 1부터 9까지의 숫자가 중복 없이 1개씩 들어갑니다.": ": Cada fila, columna y cuadro de 3×3 contiene un número del 1 al 9 sin duplicados.",
    ": 전문가 난이도는 단 0~2개의 1칸 확정 단서만 주어지지만, 결코 임의로 찍을 필요 없이 100% 논리만으로 완벽히 풀리도록 설계되었습니다.": ": La dificultad Experto solo da de 0 a 2 pistas de 1 cuadrado, pero está diseñada para resolverse completamente usando 100% de lógica, sin necesidad de adivinar al azar.",
    ": 판은 처음에 완전히 비어있습니다. 단, 1칸짜리 케이지(예: 좌상단 7)는 그 칸의 숫자가 확정 7이므로, 이 칸들을 출발점으로 삼아 연역적 추론을 전개합니다.": ": El tablero inicialmente está completamente vacío. Sin embargo, en una jaula de una sola celda (por ejemplo, 7 en la esquina superior izquierda), el número en esa celda es un 7 definido, por lo que el razonamiento deductivo se desarrolla utilizando estas celdas como punto de partida.",
