    "• 따라서 어떠한 개인정보도 판매되거나 제3자에게 제공되지 않습니다.": "• Por lo tanto, no se vende ni proporciona información personal a terceros.",
    "• 모든 게임 전적, 최근 20판 리플레이, 개인 설정은 기기 로컬 저장소에만 안전하게 보관됩니다.": "• Todas las estadísticas de tu juego, las últimas 20 repeticiones y la configuración personal se mantienen seguras solo en el almacenamiento local de tu dispositivo.",
    "• 본 앱은 외부 광고 SDK나 사용자 추적 코드가 일절 포함되어 있지 않습니다.": "• Esta aplicación no contiene ningún SDK de publicidad externa ni código de seguimiento de usuarios.",
    "• 썸도쿠는 사용자의 어떠한 개인정보도 외부 서버로 수집, 저장 또는 전송하지 않습니다.": "• Somedoku no recopila, almacena ni transmite ninguna información personal de los usuarios a servidores externos.",
