    "같은 Wi-Fi에 연결한 뒤 방장 화면의 4자리 코드를 입력하세요. 같은 Wi-Fi에 방이 여러 개 있어도 코드로 구분됩니다. 학교 Wi-Fi처럼 IP 앞자리가 서로 달라도 찾을 수 있습니다. 그래도 못 찾으면 방장 화면에 보이는 IP 주소(또는 끝 두 자리, 예: 18.247)를 입력하세요.": "Conéctate al mismo Wi-Fi e ingresa el código de 4 dígitos en la pantalla del administrador de sala. Incluso si hay varias habitaciones con el mismo Wi-Fi, están separadas por código. Al igual que el Wi-Fi de la escuela, puedes encontrarlo incluso si la dirección IP es diferente. Si aún no puede encontrarlo, ingrese la dirección IP que se muestra en la pantalla del host (o los dos últimos dígitos, por ejemplo, 18.247).",
