    "합계가 {0}인 2칸 케이지는 오직 {{1}, {2}} 조합만 가능합니다. 그런데 이 칸의 행·열·박스에 {3}이 이미 존재하므로, 이 칸은 {4}로 확정됩니다.": "Sólo {{1}, {2}} combinaciones son posibles para una jaula de 2 espacios con un total de {0}. Sin embargo, dado que {3} ya existe en la fila, columna y cuadro de esta celda, esta celda se confirma como {4}.",
    "행·열 강조": "Resaltar filas y columnas",
    "행·열·박스의 상호 제약과 케이지 목표 합계에 따라 논리적으로 유일하게 {0}이 확정됩니다.": "{0} se determina de forma lógica y única según las restricciones mutuas de filas, columnas y cuadros y la suma del objetivo de la jaula.",
