    "케이지 합계 추론과 결합된 수학 퍼즐 모드(스피드 레이스, 타임어택 점수전)를 홈 화면 및 새 게임 모달에서 자유롭게 즐기실 수 있습니다.": "Puedes disfrutar libremente de los modos de acertijos matemáticos (carrera de velocidad, batalla de puntuación contrarreloj) combinados con razonamiento de suma de jaula en la pantalla de inicio y un nuevo modo de juego.",
    "케이지마다 옅은 색을 칠해 경계를 쉽게 읽습니다": "Cada jaula está pintada en un color claro para que los límites sean fáciles de leer.",
    "케이지의 다른 모든 칸이 채워져, 남은 합계 계산에 의해 이 칸의 숫자는 7로 확정됩니다.": "Todas las demás celdas de la jaula se llenan y se confirma que el número en esta celda es 7 calculando el total restante.",
    "케이지의 목표 합계({0})와 행·열·3×3 박스의 45의 법칙(Rule of 45) 및 숫자 중복 금지 제약을 연립하면, 모순 없이 성립하는 유일한 숫자는 {1}입니다.": "Si combinamos la suma objetivo de Cage ({0}) con la Regla del 45 para filas, columnas y cuadros de 3×3, y la restricción de prohibir la duplicación de números, el único número que se cumple sin contradicción es {1}.",
    "켜짐": "En",
    "코드 {0}인 방을 찾지 못했습니다. 방장 화면에 보이는 IP 주소를 그대로 입력하거나 끝 두 자리만(예: 18.247) 입력해 접속해 보세요. 학교·회사 Wi-Fi는 기기끼리 통신을 막는 경우가 있어, IP로도 안 되면 한 사람의 휴대폰 핫스팟에 함께 연결해 주세요.": "No se pudo encontrar espacio con el código {0}. Intente conectarse ingresando la dirección IP que se muestra en la pantalla del host tal como está, o ingresando solo los dos últimos dígitos (por ejemplo, 18.247). El Wi-Fi de la escuela y la empresa puede bloquear la comunicación entre dispositivos, por lo que si la IP no funciona, conéctese juntos al punto de acceso del teléfono celular de una persona.",
