    ": 각 점선 구역 내부 숫자의 총합은 좌상단에 적힌 목표 합계와 같아야 하며, 같은 케이지 내부에서는 숫자가 중복될 수 없습니다.": ": Le nombre total de nombres à l'intérieur de chaque zone pointillée doit être égal au total cible écrit dans le coin supérieur gauche, et les nombres ne peuvent pas se chevaucher dans la même cage.",
