    "• 모든 게임 전적, 최근 20판 리플레이, 개인 설정은 기기 로컬 저장소에만 안전하게 보관됩니다.": "• Toutes vos statistiques de jeu, vos 20 dernières rediffusions et vos paramètres personnels sont conservés en sécurité uniquement dans le stockage local de votre appareil.",
