    "같은 Wi-Fi에 연결한 뒤 방장 화면의 4자리 코드를 입력하세요. 같은 Wi-Fi에 방이 여러 개 있어도 코드로 구분됩니다. 학교 Wi-Fi처럼 IP 앞자리가 서로 달라도 찾을 수 있습니다. 그래도 못 찾으면 방장 화면에 보이는 IP 주소(또는 끝 두 자리, 예: 18.247)를 입력하세요.": "Connectez-vous au même Wi-Fi et entrez le code à 4 chiffres sur l'écran du gestionnaire de salle. Même s’il existe plusieurs pièces équipées du même Wi-Fi, elles sont séparées par un code. Comme le Wi-Fi scolaire, vous pouvez le trouver même si l’adresse IP est différente. Si vous ne le trouvez toujours pas, saisissez l'adresse IP affichée sur l'écran hôte (ou les deux derniers chiffres, par exemple 18.247).",
