    "케이지마다 옅은 색을 칠해 경계를 쉽게 읽습니다": "Chaque cage est peinte d'une couleur claire pour rendre les limites faciles à lire",
    "케이지의 다른 모든 칸이 채워져, 남은 합계 계산에 의해 이 칸의 숫자는 7로 확정됩니다.": "Toutes les autres cellules de la cage sont remplies et le nombre dans cette cellule est confirmé comme étant 7 en calculant le total restant.",
    "케이지의 목표 합계({0})와 행·열·3×3 박스의 45의 법칙(Rule of 45) 및 숫자 중복 금지 제약을 연립하면, 모순 없이 성립하는 유일한 숫자는 {1}입니다.": "Si l'on combine la somme cible de Cage ({0}) avec la règle des 45 pour les lignes, les colonnes et les cases 3×3, et la contrainte d'interdire la duplication des nombres, le seul nombre qui tient sans contradiction est {1}.",
    "켜짐": "Activé",
    "코드 {0}인 방을 찾지 못했습니다. 방장 화면에 보이는 IP 주소를 그대로 입력하거나 끝 두 자리만(예: 18.247) 입력해 접속해 보세요. 학교·회사 Wi-Fi는 기기끼리 통신을 막는 경우가 있어, IP로도 안 되면 한 사람의 휴대폰 핫스팟에 함께 연결해 주세요.": "Impossible de trouver la salle avec le code {0}. Essayez de vous connecter en saisissant l'adresse IP affichée telle quelle sur l'écran hôte, ou en saisissant uniquement les deux derniers chiffres (par exemple 18.247). Le Wi-Fi de l'école et de l'entreprise peut bloquer la communication entre les appareils. Si l'IP ne fonctionne pas, connectez-vous ensemble au point d'accès du téléphone portable d'une personne.",
