    "1. 각 행과 열, 3×3 블록에 1부터 9까지의 숫자가 중복 없이 하나씩 들어갑니다.": "1. Die Zahlen 1 bis 9 werden einzeln in jede Zeile, Spalte und jeden 3×3-Block ohne Duplikate eingegeben.",
