    "2칸 3(1+2), 2칸 4(1+3), 2칸 16(7+9), 2칸 17(8+9) 등은 후보수를 급격히 좁혀줍니다.": "2 Leerzeichen 3(1+2), 2 Leerzeichen 4(1+3), 2 Leerzeichen 16(7+9), 2 Leerzeichen 17(8+9) usw. schränken die Anzahl der Kandidaten drastisch ein.",
    "3. 시작 앵커 힌트": "3. Ankerhinweis starten",
    "3. 하나의 케이지 안에서는 동일한 숫자가 중복될 수 없습니다.": "3. Die gleiche Anzahl kann nicht innerhalb eines Käfigs dupliziert werden.",
    "3×3 블록 또는 1개 행의 모든 수의 합은 항상 45입니다. 박스를 삐져나온 케이지의 차이로 특정 칸을 100% 확정할 수 있습니다.": "Die Summe aller Zahlen in einem 3×3-Block oder einer Reihe beträgt immer 45. Eine bestimmte Box kann durch den Unterschied des aus der Box herausragenden Käfigs zu 100 % bestätigt werden.",
    "3단계: 인간 연역 추론 검증 완료! ({0}/81칸 확정)": "Schritt 3: Überprüfung des menschlichen deduktiven Denkens abgeschlossen! ({0}/81 Plätze bestätigt)",
    "3단계: 인간 연역 판별 중... ({0}/81칸 확정 · 시도 #{1})": "Schritt 3: Bestimmung des menschlichen Abzugs... ({0}/81 Leerzeichen bestätigt · Versuch Nr.{1})",
