    "1단계: 9×9 라틴 방진 완성 스도쿠 판 생성": "Schritt 1: Erstellen Sie ein Sudoku-Brett, um das 9×9 lateinische Quadrat zu vervollständigen.",
    "1단계: 9×9 완성 스도쿠 정답판 생성 중...": "Schritt 1: Generieren des 9×9 vollständigen Sudoku-Antwortschlüssels ...",
