    "1칸짜리 시작 앵커 케이지입니다. 목표 합계가 {0}이므로 이 칸은 다른 계산 없이 즉시 {1}로 확정됩니다.": "Dies ist ein 1-Feld-Startankerkäfig. Da die Zielsumme {0} ist, wird diese Zelle ohne weitere Berechnungen sofort als {1} bestätigt.",
    "2. 점선으로 둘러싸인 케이지(Cage) 안의 숫자 합은 좌측 상단에 표시된 합계와 정확히 일치해야 합니다.": "2. Die Summe der Zahlen im Käfig, umgeben von einer gepunkteten Linie, muss genau mit der Summe übereinstimmen, die in der oberen linken Ecke angezeigt wird.",
