    "Wi-Fi 주소를 확인할 수 없습니다. 같은 Wi-Fi에 연결해 주세요.": "Die WLAN-Adresse kann nicht bestätigt werden. Bitte stellen Sie eine Verbindung zum gleichen WLAN her.",
    "[Sumdoku] 영구 백업 데이터 {0}개 항목 자동 복원 완료": "[Zusammenfassung] Automatische Wiederherstellung von {0} Elementen permanenter Sicherungsdaten abgeschlossen.",
    "[Sumdoku] 영구 백업 복원 중 오류:": "[Zusammenfassung] Fehler beim Wiederherstellen der dauerhaften Sicherung:",
