    "[{0}:{1}] ({2}행, {3}열) 칸에 숫자 {4} 입력 ({5})": "[{0}:{1}] ({2} Zeile, {3} Spalte) Geben Sie die Zahl {4} ({5}) ein.",
    "[메모]": "[Memo]",
    "[추가 힌트] {0} 확정! (보너스 힌트 제공, -50점)": "[Zusätzlicher Hinweis] {0} Bestätigt! (Bonushinweis bereitgestellt, -50 Punkte)",
    "9개의 셀에 모두 채워 넣은 숫자를 키패드에서 비활성화합니다": "Deaktiviert die Eingabe von Zahlen in alle 9 Zellen der Tastatur.",
    ": 각 점선 구역 내부 숫자의 총합은 좌상단에 적힌 목표 합계와 같아야 하며, 같은 케이지 내부에서는 숫자가 중복될 수 없습니다.": ": Die Gesamtzahl der Zahlen innerhalb jedes gepunkteten Bereichs muss der in der oberen linken Ecke geschriebenen Zielsumme entsprechen, und Zahlen dürfen sich innerhalb desselben Käfigs nicht überlappen.",
    ": 모든 행, 열, 3×3 박스에 1부터 9까지의 숫자가 중복 없이 1개씩 들어갑니다.": ": Jede Zeile, Spalte und jedes 3×3-Feld enthält eine Zahl von 1 bis 9 ohne Duplikate.",
    ": 전문가 난이도는 단 0~2개의 1칸 확정 단서만 주어지지만, 결코 임의로 찍을 필요 없이 100% 논리만으로 완벽히 풀리도록 설계되었습니다.": ": Der Schwierigkeitsgrad „Experte“ gibt nur 0 bis 2 1-Quadrat-Hinweise, ist aber so konzipiert, dass er mit 100 % Logik vollständig gelöst werden kann, ohne dass zufälliges Raten erforderlich ist.",
    ": 판은 처음에 완전히 비어있습니다. 단, 1칸짜리 케이지(예: 좌상단 7)는 그 칸의 숫자가 확정 7이므로, 이 칸들을 출발점으로 삼아 연역적 추론을 전개합니다.": ": Das Board ist zunächst komplett leer. In einem Käfig mit nur einer Zelle (z. B. 7 oben links) ist die Zahl in dieser Zelle jedoch eine eindeutige 7, sodass deduktives Denken unter Verwendung dieser Zellen als Ausgangspunkt entwickelt wird.",
