    "같은 Wi-Fi에 연결한 뒤 방장 화면의 4자리 코드를 입력하세요. 같은 Wi-Fi에 방이 여러 개 있어도 코드로 구분됩니다. 학교 Wi-Fi처럼 IP 앞자리가 서로 달라도 찾을 수 있습니다. 그래도 못 찾으면 방장 화면에 보이는 IP 주소(또는 끝 두 자리, 예: 18.247)를 입력하세요.": "Stellen Sie eine Verbindung zum gleichen WLAN her und geben Sie den 4-stelligen Code auf dem Raummanager-Bildschirm ein. Auch wenn es mehrere Räume mit demselben WLAN gibt, sind diese durch einen Code getrennt. Wie beim Schul-WLAN können Sie es auch dann finden, wenn die IP-Adresse unterschiedlich ist. Wenn Sie es immer noch nicht finden können, geben Sie die auf dem Host-Bildschirm angezeigte IP-Adresse ein (oder die letzten beiden Ziffern, z. B. 18.247).",
