    "썸도쿠 퍼즐을 처음으로 클리어 완료": "Das Somedoku-Rätsel zum ersten Mal gelöst.",
    "아닙니다. 썸도쿠의 모든 퍼즐은 찍기 없이 100% 연역적 추론만으로 정답이 유일하게 풀리도록 정밀 검증되어 생성됩니다.": "Nein. Alle Rätsel von Somedoku werden sorgfältig überprüft und erstellt, um sicherzustellen, dass die einzig richtige Antwort durch 100 % deduktives Denken ohne Stempeln gelöst wird.",
    "아래 '준비 완료' 버튼을 눌러주세요.": "Bitte klicken Sie unten auf die Schaltfläche „Bereit“.",
    "연결 시간이 초과되었습니다. 방이 열려 있는지 확인해 주세요. 학교·회사 Wi-Fi는 기기끼리 통신을 막는 경우가 있어, 그럴 때는 한 사람의 휴대폰 핫스팟에 함께 연결해 주세요.": "Zeitüberschreitung bei der Verbindung. Bitte überprüfen Sie, ob das Zimmer geöffnet ist. WLAN in der Schule oder am Arbeitsplatz kann die Kommunikation zwischen Geräten blockieren. Stellen Sie in diesem Fall gemeinsam eine Verbindung zum Mobiltelefon-Hotspot einer Person her.",
