    "최고 점수": "Höchste Punktzahl",
    "최고 점수·시간 기록은 저장된 리플레이 중 퍼즐을 완성한 성공 기록 기준입니다. 기권승은 제외합니다. 리플레이는 최근 최대 20판이며, 이전 난이도별 전체 게임 수는 기록이 없어 표시하지 않습니다.": "Die höchste Punktzahl/Zeit basiert auf dem Erfolg beim Lösen des Rätsels während gespeicherter Wiederholungen. Gewinner durch Rücknahme sind ausgeschlossen. Wiederholungen sind bis zu den letzten 20 Spielen möglich, und die Gesamtzahl der vorherigen Spiele nach Schwierigkeitsgrad wird nicht angezeigt, da keine Aufzeichnung vorhanden ist.",
