    "케이지 합계 및 0-2개 앵커 추론 기법": "Käfigsummen- und 0-2-Anker-Inferenztechniken",
    "케이지 합계 추론과 결합된 수학 퍼즐 모드(스피드 레이스, 타임어택 점수전)를 홈 화면 및 새 게임 모달에서 자유롭게 즐기실 수 있습니다.": "Sie können Mathe-Puzzle-Modi (Geschwindigkeitsrennen, Zeitangriffs-Score-Kampf) in Kombination mit Käfigsummen-Überlegungen auf dem Startbildschirm und einem neuen Spielmodus frei genießen.",
    "케이지마다 옅은 색을 칠해 경계를 쉽게 읽습니다": "Jeder Käfig ist in einer hellen Farbe bemalt, damit die Grenzen gut lesbar sind",
    "케이지의 다른 모든 칸이 채워져, 남은 합계 계산에 의해 이 칸의 숫자는 7로 확정됩니다.": "Alle anderen Zellen im Käfig werden gefüllt und die Anzahl in dieser Zelle wird durch Berechnung der verbleibenden Gesamtsumme mit 7 bestätigt.",
    "케이지의 목표 합계({0})와 행·열·3×3 박스의 45의 법칙(Rule of 45) 및 숫자 중복 금지 제약을 연립하면, 모순 없이 성립하는 유일한 숫자는 {1}입니다.": "Wenn wir Cages Zielsumme ({0}) mit der Regel von 45 für Zeilen, Spalten und 3×3-Boxen und der Einschränkung, das Duplizieren von Zahlen zu verbieten, kombinieren, ist {1} die einzige Zahl, die ohne Widerspruch gilt.",
    "켜짐": "Ein",
    "코드 {0}인 방을 찾지 못했습니다. 방장 화면에 보이는 IP 주소를 그대로 입력하거나 끝 두 자리만(예: 18.247) 입력해 접속해 보세요. 학교·회사 Wi-Fi는 기기끼리 통신을 막는 경우가 있어, IP로도 안 되면 한 사람의 휴대폰 핫스팟에 함께 연결해 주세요.": "Es konnte kein Raum mit Code {0} gefunden werden. Versuchen Sie, eine Verbindung herzustellen, indem Sie die auf dem Host-Bildschirm angezeigte IP-Adresse unverändert eingeben oder nur die letzten beiden Ziffern (z. B. 18.247). Das WLAN der Schule und des Unternehmens blockiert möglicherweise die Kommunikation zwischen Geräten. Wenn IP nicht funktioniert, stellen Sie daher gemeinsam eine Verbindung zum Mobiltelefon-Hotspot einer Person her.",
