    "4~5개 확정 앵커": "4-5个已确认的主播",
    "4자리 코드로 접속 · 안 되면 IP {0} 입력": "使用 4 位代码连接 · 如果没有，请输入 IP {0}",
    "5연승 달성": "取得5连胜",
    "5회 이상 퍼즐 클리어 성공": "成功通关谜题5次以上",
    "6개 확정 앵커": "6 个已确认的主播",
    "8개 확정 앵커": "8名已确认主播",
    "9개의 셀에 모두 채워 넣은 숫자를 키패드에서 비활성화합니다": "禁用键盘上所有 9 个单元格中填写的数字。",
    ": 각 점선 구역 내부 숫자의 총합은 좌상단에 적힌 목표 합계와 같아야 하며, 같은 케이지 내부에서는 숫자가 중복될 수 없습니다.": "：每个虚线区域内的数字总数必须等于左上角所写的目标总数，并且同一笼内的数字不能重叠。",
    ": 모든 행, 열, 3×3 박스에 1부터 9까지의 숫자가 중복 없이 1개씩 들어갑니다.": "：每行、每列、3×3的方框中包含1到9中的一个数字，且不重复。",
    ": 전문가 난이도는 단 0~2개의 1칸 확정 단서만 주어지지만, 결코 임의로 찍을 필요 없이 100% 논리만으로 완벽히 풀리도록 설계되었습니다.": "：专家难度只给出0到2个1平方的线索，但它被设计为使用100%逻辑完全解决，不需要随机猜测。",
    ": 판은 처음에 완전히 비어있습니다. 단, 1칸짜리 케이지(예: 좌상단 7)는 그 칸의 숫자가 확정 7이므로, 이 칸들을 출발점으로 삼아 연역적 추론을 전개합니다.": "：棋盘最初是完全空的。然而，在单细胞笼中（例如左上角的 7），该细胞中的数字是确定的 7，因此以这些细胞为起点来发展演绎推理。",
    "API 응답 실패": "API响应失败",
    "Android 앱에서 방을 생성할 수 있습니다.": "您可以在 Android 应用程序中创建房间。",
