    "3단계: 인간 연역 판별 중... ({0}/81칸 확정 · 시도 #{1})": "第 3 步：确定人为推论...（已确认 {0}/81 个空格 · 尝试 #{1}）",
    "3분 이내에 퍼즐 완료": "在 3 分钟内完成拼图",
